function SimpleForm({ label, placeholder, button, submit, error }: { label: string; placeholder: string; button: string; submit: (value: string) => Promise<unknown>; error: (e: unknown) => void }) { const [value, setValue] = useState(''), [busy, setBusy] = useState(false); return <form className="simple-form" onSubmit={e => { e.preventDefault(); setBusy(true); void submit(value).catch(error).finally(() => setBusy(false)); }}><label>{label}<input required value={value} placeholder={placeholder} onChange={e => setValue(e.target.value)} maxLength={500}/></label><button className="primary" disabled={busy}>{busy ? 'Working…' : button}<ArrowRight size={17}/></button></form>; }
function SettingsForm({ me, refresh, error, logout }: { me: PublicUser; refresh: () => Promise<void>; error: (e: unknown) => void; logout: () => Promise<void> }) {
  const [name, setName] = useState(me.displayName), [bio, setBio] = useState(me.bio), [status, setStatus] = useState(me.status === 'offline' ? 'online' : me.status), [current, setCurrent] = useState(''), [password, setPassword] = useState(''), [secret, setSecret] = useState(''), [saved, setSaved] = useState(false), [busy, setBusy] = useState(false);
  return <div className="settings-form"><form onSubmit={e => { e.preventDefault(); setBusy(true); void request('/profile', { displayName: name, bio, status }, 'PATCH').then(refresh).then(() => { setSaved(true); setTimeout(() => setSaved(false), 3000); }).catch(error).finally(() => setBusy(false)); }}><div className="avatar-upload"><Avatar user={me}/><label className="secondary">Change avatar<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e => { const file = e.target.files?.[0]; if (!file) return; const form = new FormData(); form.set('avatar', file); void request('/profile/avatar', form).then(refresh).catch(error); }}/></label><small>PNG, JPG or WebP · up to 256 KB</small></div><label>Display name<input required maxLength={48} value={name} onChange={e => setName(e.target.value)}/></label><label>About you<textarea maxLength={500} value={bio} onChange={e => setBio(e.target.value)} placeholder="A little about yourself…"/></label><label>Status<select value={status} onChange={e => setStatus(e.target.value as typeof status)}><option value="online">Online</option><option value="idle">Idle</option><option value="busy">Do not disturb</option></select></label><button className="primary" disabled={busy}>{saved ? <><Check size={17}/> Saved</> : 'Save your profile'}</button></form><details><summary>Change password</summary><form onSubmit={e => { e.preventDefault(); void request('/auth/password', { currentPassword: current, password }).then(() => { setCurrent(''); setPassword(''); }).catch(error); }}><label>Current password<input required type="password" autoComplete="current-password" value={current} onChange={e => setCurrent(e.target.value)}/></label><label>New password<input required minLength={10} type="password" autoComplete="new-password" value={password} onChange={e => setPassword(e.target.value)}/></label><button className="secondary">Update password</button></form></details>{!me.instanceAdmin && <details><summary>Instance administration</summary><form onSubmit={e => { e.preventDefault(); void request('/admin/claim', { secret }).then(refresh).catch(error); }}><label>Single-use bootstrap secret<input type="password" value={secret} onChange={e => setSecret(e.target.value)}/></label><button className="secondary">Claim administration</button></form></details>}<button className="logout-button" onClick={() => { void logout().catch(error); }}><LogOut size={17}/> Sign out</button></div>;
}
function ManageServer({ server, channels, members, refresh, error }: { server: Server; channels: Channel[]; members: { user: PublicUser; role: Role }[]; refresh: () => Promise<void>; error: (e: unknown) => void }) {
  const [name, setName] = useState(server.name), [channelName, setChannelName] = useState(''), [kind, setKind] = useState<'text' | 'voice'>('text'), [invite, setInvite] = useState(''), [tab, setTab] = useState('overview'), [targetChannel, setTargetChannel] = useState(channels[0]?.id || ''), [role, setRole] = useState<Role>('member'), [perms, setPerms] = useState<Partial<Record<Permission, boolean>>>({}), [deleteConfirm, setDeleteConfirm] = useState('');
  const manage = ['owner', 'administrator'].includes(server.role);
  return <div className="manage-server"><div className="tabs">{['overview', 'channels', 'members', 'permissions'].map(t => <button className={tab === t ? 'selected' : ''} onClick={() => setTab(t)} key={t}>{t}</button>)}</div>{tab === 'overview' && <><form onSubmit={e => { e.preventDefault(); void request(`/servers/${server.id}`, { name }, 'PATCH').then(refresh).catch(error); }}><label>Server name<input value={name} onChange={e => setName(e.target.value)} required maxLength={64} disabled={!manage}/></label>{manage && <button className="primary">Save changes</button>}</form>{['owner', 'administrator', 'moderator'].includes(server.role) && <section className="invite-section"><h3>Good company starts with an invite.</h3><p>Invite links expire after 24 hours and allow 10 joins.</p><button className="secondary" onClick={() => { void request(`/servers/${server.id}/invites`, {}).then(result => setInvite(result.url)).catch(error); }}><Plus size={16}/> Create invite link</button>{invite && <div className="invite-link"><input aria-label="Invite link" readOnly value={invite}/><IconButton title="Copy invite" onClick={() => { void navigator.clipboard.writeText(invite).catch(error); }}><Copy/></IconButton></div>}</section>}{server.role === 'owner' && <details className="danger-zone"><summary>Delete this server</summary><p>This removes its channels, messages, and membership. Type the server name to confirm.</p><input aria-label="Confirm server name" value={deleteConfirm} onChange={e => setDeleteConfirm(e.target.value)}/><button className="danger-button" disabled={deleteConfirm !== server.name} onClick={() => { void request(`/servers/${server.id}`, { delete: true }, 'PATCH').then(refresh).catch(error); }}>Permanently delete server</button></details>}</>}{tab === 'channels' && <>{manage && <form className="channel-form" onSubmit={e => { e.preventDefault(); void request(`/servers/${server.id}/channels`, { name: channelName, kind }).then(refresh).then(() => setChannelName('')).catch(error); }}><label>Channel name<input required maxLength={64} value={channelName} onChange={e => setChannelName(e.target.value)} placeholder="A new conversation"/></label><label>Type<select value={kind} onChange={e => setKind(e.target.value as typeof kind)}><option value="text">Text</option><option value="voice">Voice</option></select></label><button className="primary"><Plus size={17}/> Add</button></form>}{channels.map(ch => <ChannelManager key={ch.id} channel={ch} manage={manage} refresh={refresh} error={error}/>)}</>}{tab === 'members' && members.map(m => <div className="manage-member" key={m.user.id}><Avatar user={m.user} small/><span>{m.user.displayName}</span><select aria-label={`Role for ${m.user.displayName}`} value={m.role} disabled={!manage || m.role === 'owner'} onChange={e => { void request(`/servers/${server.id}/members/${m.user.id}`, { role: e.target.value }, 'PATCH').then(refresh).catch(error); }}><option value="owner" disabled>Owner</option><option value="administrator">Administrator</option><option value="moderator">Moderator</option><option value="member">Member</option></select>{m.role !== 'owner' && ['owner', 'administrator', 'moderator'].includes(server.role) && <IconButton title={`Remove ${m.user.displayName}`} danger onClick={() => { void request(`/servers/${server.id}/members/${m.user.id}`, { remove: true }, 'PATCH').then(refresh).catch(error); }}><X/></IconButton>}</div>)}{tab === 'permissions' && <form onSubmit={e => { e.preventDefault(); void request(`/channels/${targetChannel}`, { role, permissions: perms }, 'PATCH').then(refresh).catch(error); }}><p>Overrides apply to the selected role in this channel. Owners retain all permissions. Inherit restores the role default.</p><label>Channel<select value={targetChannel} onChange={e => setTargetChannel(e.target.value)}>{channels.map(ch => <option key={ch.id} value={ch.id}>{ch.name}</option>)}</select></label><label>Role<select value={role} onChange={e => setRole(e.target.value as Role)}><option value="member">Member</option><option value="moderator">Moderator</option><option value="administrator">Administrator</option></select></label>{(['view', 'write', 'speak', 'share', 'moderate', 'manageChannels'] as Permission[]).map(p => <label className="permission-row" key={p}>{p}<select value={perms[p] === undefined ? '' : String(perms[p])} onChange={e => setPerms(old => { const value = { ...old }; if (e.target.value === '') delete value[p]; else value[p] = e.target.value === 'true'; return value; })}><option value="">Inherit</option><option value="true">Allow</option><option value="false">Deny</option></select></label>)}<button className="primary" disabled={!manage}>Save channel overrides</button></form>}</div>;
}
function ChannelManager({ channel, manage, refresh, error }: { channel: Channel; manage: boolean; refresh: () => Promise<void>; error: (e: unknown) => void }) { const [name, setName] = useState(channel.name), [remove, setRemove] = useState(false); return <div className="channel-manager">{channel.kind === 'text' ? <Hash size={18}/> : <Volume2 size={18}/>}<input aria-label={`Rename ${channel.name}`} value={name} disabled={!manage} onChange={e => setName(e.target.value)}/>{manage && <><IconButton title={`Save ${channel.name}`} onClick={() => { void request(`/channels/${channel.id}`, { name }, 'PATCH').then(refresh).catch(error); }}><Check/></IconButton><IconButton title={`Delete ${channel.name}`} danger onClick={() => setRemove(!remove)}><Trash2/></IconButton>{remove && <button className="danger-button" onClick={() => { void request(`/channels/${channel.id}`, { delete: true }, 'PATCH').then(refresh).catch(error); }}>Confirm delete</button>}</>}</div>; }
